import copy

test_input = [
    [8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 5, 8, 8],
    [8, 5, 5, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8]
]

def solve(grid):
    result = copy.deepcopy(grid)
    nrows, ncols = len(grid), len(grid[0])

    for r in range(1, nrows):
        # Find all marker columns
        markers = [c for c, v in enumerate(grid[r]) if v == 5]
        if not markers:
            continue

        # Process segments between consecutive markers
        # Also handle the last segment (after last marker to edge)
        for i in range(len(markers) - 1):
            seg_start = markers[i] + 1
            seg_end = markers[i + 1]

            if seg_start < seg_end:
                for c in range(seg_start, seg_end):
                    result[r][c] = 3

        # Last segment (after last marker)
        last_marker = markers[-1]
        seg_start = last_marker + 1

        # Find min marker from all other rows
        other_markers = []
        for other_r in range(nrows):
            if other_r == r:
                continue
            other_markers.extend([c for c, v in enumerate(grid[other_r]) if v == 5])

        if other_markers:
            min_other = min(other_markers)
            seg_end = min(seg_end, min_other + ncols + 1)  # Add buffer

            # If seg_end < seg_start, segment is empty (no fill)
            if seg_start < seg_end:
                for c in range(seg_start, min(seg_end, ncols)):
                    result[r][c] = 3

    return result

result = solve(test_input)
print("Predicted output:")
for r in range(3):
    print(f"Row {r}: " + " ".join(map(str, result[r])))

